package dev.zomboid.mts;
import java.util.*;
public final class FamilyWorkshop {
 static String p="minecrafttransportsimulator.";
 public enum Kind {CAR,HELICOPTER,BOAT,MOTORCYCLE,PLANE}
 public record Target(String label,Object part,Double health){}
 static final class View {int page,selected;Object status,outline;List<Object> buttons=new ArrayList<>();}
 static final Map<Object,View> views=new WeakHashMap<>();
 public static Kind kind(Object v){Object d=R.get(v,"definition");String id=R.get(d,"systemName").toString().toLowerCase(Locale.ROOT);List<?> slots=(List<?>)R.get(d,"parts");int wheels=0;boolean air=R.yes(R.get(R.get(d,"motorized"),"isAircraft")),heli=false,engine=false;for(Object slot:slots){Collection<?> types=(Collection<?>)R.get(slot,"types");if(types.stream().anyMatch(t->t.toString().startsWith("ground_wheel")))wheels++;for(Object t:types){String s=t.toString();heli|=s.startsWith("engine_helicopter")||s.startsWith("propeller_rotor");air|=s.startsWith("engine_aircraft")||s.startsWith("engine_jet");engine|=s.startsWith("engine");}}if(heli)return Kind.HELICOPTER;if(air)return Kind.PLANE;if(id.contains("motorcycle")||id.contains("chopper")||id.contains("motorbike")||id.contains("scooter")||wheels>0&&wheels<=2&&engine)return Kind.MOTORCYCLE;if(wheels==0&&!Mechanics.car(v))return Kind.BOAT;return Kind.CAR;}
 public static boolean special(Object v){return kind(v)!=Kind.CAR;}
 public static String title(Kind k){return switch(k){case HELICOPTER->"MECANICA · HELICOPTERO";case BOAT->"MECANICA · EMBARCACION";case MOTORCYCLE->"MECANICA · MOTO";case PLANE->"MECANICA · AVION";default->"MECANICA DEL VEHICULO";};}
 public static String structure(Kind k){return switch(k){case BOAT->"Casco";case MOTORCYCLE->"Bastidor";case HELICOPTER,PLANE->"Fuselaje";default->"Chasis";};}
 public static String texture(Object v){Kind k=kind(v);return k==Kind.CAR?"mts:textures/guis/workshop_car.png":"mts:textures/guis/workshop_"+k.name().toLowerCase(Locale.ROOT)+".png";}
 static String label(Collection<?> types,Kind kind){for(Object t:types){String s=t.toString();if(s.startsWith("engine"))return "Motor";if(s.startsWith("propeller_rotor"))return "Rotor";if(s.startsWith("propeller"))return kind==Kind.HELICOPTER?"Rotor / helice":"Helice";if(s.startsWith("ground_wheel"))return kind==Kind.PLANE?"Rueda de aterrizaje":"Rueda";if(s.startsWith("ground_skid"))return "Patin de aterrizaje";if(s.startsWith("ground_pontoon"))return "Flotador";if(s.startsWith("seat"))return kind==Kind.BOAT?"Asiento / timon":"Asiento";if(s.startsWith("interactable"))return "Almacenamiento";if(s.contains("battery"))return "Bateria";if(s.contains("wing"))return "Ala";}return "Pieza auxiliar";}
 public static List<Target> targets(Object v){Kind k=kind(v);List<Target> rows=new ArrayList<>();rows.add(new Target(structure(k),v,Mechanics.health(v)*100));List<?> slots=(List<?>)R.get(R.get(v,"definition"),"parts"),parts=(List<?>)R.get(v,"partsInSlots");Set<Object> seen=Collections.newSetFromMap(new IdentityHashMap<>());Map<String,Integer> counts=new HashMap<>();for(int i=0;i<slots.size();i++){Object part=i<parts.size()?parts.get(i):null;String name=label((Collection<?>)R.get(slots.get(i),"types"),k);rows.add(new Target(name+" "+counts.merge(name,1,Integer::sum),part,part==null?null:Mechanics.health(part)*100));if(part!=null)seen.add(part);}for(Object part:(Collection<?>)R.get(v,"allParts"))if(seen.add(part)){String type=R.get(R.get(R.get(part,"definition"),"generic"),"type").toString(),name=label(List.of(type),k);rows.add(new Target(name+" "+counts.merge(name,1,Integer::sum),part,Mechanics.health(part)*100));}return rows;}
 static Object text(Object gui,int x,int y,String s,float size){return R.call(Mechanics.class,"label",gui,x,y,s,size,R.get(R.type(p+"baseclasses.ColorRGB"),"WHITE"));}
 static Object button(Object gui,int x,int y,int width,String action,String label){Object b=R.make("dev.zomboid.mts.VehicleButton",gui,x,y,width,action,label);R.set(b,"ignoreGUILightingState",true);R.call(gui,"addComponent",b);return b;}
 public static void setup(Object gui){Object v=R.get(gui,"vehicle");int x=((Number)R.get(gui,"guiLeft")).intValue(),y=((Number)R.get(gui,"guiTop")).intValue();Object bg=R.get(gui,"background");if(bg!=null)R.set(bg,"ignoreGUILightingState",true);View view=new View();views.put(gui,view);text(gui,x+18,y+16,title(kind(v)),1.1f);text(gui,x+210,y+54,"Selecciona la pieza a reparar",1f);view.status=text(gui,x+210,y+35,"",.9f);view.outline=R.make(p+"guis.components.GUIComponentCutout",gui,x+18,y+65,175,240,640,0,180,240);R.set(view.outline,"ignoreGUILightingState",true);R.call(gui,"addComponent",view.outline);for(int i=0;i<8;i++)view.buttons.add(button(gui,x+210,y+75+i*27,390,"service-select:"+i,""));button(gui,x+210,y+297,115,"service-prev","< Anterior");button(gui,x+335,y+297,115,"service-next","Siguiente >");button(gui,x+460,y+297,140,"service-repair","Reparar pieza");button(gui,x+210,y+331,190,"service-panel","Controles originales");text(gui,x+18,y+320,"Motor apagado",.85f);text(gui,x+18,y+335,"Vehiculo detenido",.85f);text(gui,x+410,y+339,"Kit compatible en mano",.85f);}
 public static void state(Object gui){View view=views.get(gui);if(view==null)return;Object v=R.get(gui,"vehicle");List<Target> rows=targets(v);int pages=Math.max(1,(rows.size()+7)/8);view.page=Math.min(view.page,pages-1);view.selected=Math.min(view.selected,rows.size()-1);Target selected=rows.get(view.selected);R.set(view.status,"text",String.format("Estado %.0f%% | Combustible %.0f%% | Bat %.0f%%",Mechanics.health(v)*100,Mechanics.fuel(v)*100,Mechanics.battery(v)*100));int band=Workshop.band(Mechanics.health(v)*100);R.set(view.outline,"textureXOffset",640+band%2*180);R.set(view.outline,"textureYOffset",band/2*240);for(int i=0;i<8;i++){int index=view.page*8+i;Object button=view.buttons.get(i);boolean exists=index<rows.size();R.set(button,"visible",exists);if(exists){Target t=rows.get(index);R.set(button,"text",(index==view.selected?"> ":"")+(t.health()==null?"§7":switch(Workshop.band(t.health())){case 0->"§a";case 1->"§e";default->"§c";})+t.label()+": "+(t.health()==null?"No instalado":Math.round(t.health())+"%"));R.set(button,"enabled",t.part()!=null);}}}
 static Object player(){return R.call(R.get(R.type(p+"mcinterface.InterfaceManager"),"clientInterface"),"getClientPlayer");}
 public static boolean stopped(Object v){return R.num(R.get(v,"velocity"))<.02&&((Collection<?>)R.get(v,"engines")).stream().noneMatch(e->R.yes(R.get(e,"running")));}
 static void notice(Object player,String message){R.call(Inspection.class,"message",player,message);}
 public static boolean blockRepair(Object item,Object entity,Object player,boolean right){if(!right||!"REPAIR_PACK".equals(R.get(R.get(R.get(item,"definition"),"item"),"type").toString()))return false;Object v=R.call(Mechanics.class,"vehicle",entity);if(v==null||!RoadDriving.transport(v)||stopped(v))return false;if(!R.yes(R.call(R.get(v,"world"),"isClient")))notice(player,"Apaga todos los motores y detente para reparar.");return true;}
 public static void action(Object gui,String action){View view=views.get(gui);if(view==null)return;Object v=R.get(gui,"vehicle"),player=player();if(player==null||!Inspection.allowed(v,player))return;List<Target> rows=targets(v);if(action.startsWith("service-select:")){int index=view.page*8+Integer.parseInt(action.substring(15));if(index<rows.size())view.selected=index;return;}if(action.equals("service-prev")){view.page=Math.max(0,view.page-1);return;}if(action.equals("service-next")){view.page=Math.min((rows.size()-1)/8,view.page+1);return;}if(action.equals("service-panel")){R.call(gui,"close");R.make(p+"guis.instances.GUIPanel",v);return;}if(!action.equals("service-repair"))return;if(!stopped(v)){notice(player,"Apaga todos los motores y detente para reparar.");return;}Object item=R.call(R.call(player,"getHeldStack"),"getItem");if(item==null||!R.type(p+"items.instances.ItemItem").isInstance(item)||!"REPAIR_PACK".equals(R.get(R.get(R.get(item,"definition"),"item"),"type").toString())){notice(player,"Selecciona un kit de reparacion compatible en la mano.");return;}Object target=rows.get(Math.min(view.selected,rows.size()-1)).part();if(target==null){notice(player,"Pieza ausente: debes instalarla.");return;}Collection<?> boxes=(Collection<?>)R.get(target,"collisionBoxes");if(boxes.isEmpty()){notice(player,"Esta pieza no tiene punto de reparacion accesible.");return;}Object box=boxes.iterator().next(),packets=R.get(R.type(p+"mcinterface.InterfaceManager"),"packetInterface");R.call(packets,"sendToServer",R.make(p+"packets.instances.PacketEntityInteract",target,player,box,false,true));R.call(packets,"sendToServer",R.make(p+"packets.instances.PacketEntityInteract",target,player,box,false,false));}
 public static void close(Object gui){views.remove(gui);}
}
